#!/usr/bin/env node
// Generates RBAC artifacts from firebase/rules-src/permissions.json:
//   firebase/rules-src/permission-codes.json  (each permission's 2-character code: append-only, never reused)
//   firebase/firestore.rules              (from firestore.rules.tmpl + perms() map)
//   functions/src/generated/rbac.ts       (roles, permissions, codes, areas, grantable)
//   apps/web/src/generated/rbac.ts        (same, for UI decisions only)
// `--check` exits non-zero if any generated file is stale (used in CI).
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const src = JSON.parse(readFileSync(join(root, 'firebase/rules-src/permissions.json'), 'utf8'));
const strip = (o) => Object.fromEntries(Object.entries(o).filter(([k]) => !k.startsWith('$')));
const roles = strip(src.roles);
const permissions = strip(src.permissions);
const grantable = strip(src.grantable);
const orgWide = src.orgWide.list;
const corporateOnly = src.corporateOnly.list;
const superAdminOnly = src.superAdminOnly;
const areas = src.areas;

// Validate references so a typo fails generation instead of silently denying.
const codes = new Set(Object.values(roles).map((r) => r.code));
for (const [perm, list] of Object.entries(permissions)) {
  for (const c of list) if (!codes.has(c) || c === 'SA') throw new Error(`${perm}: unknown or platform role code ${c}`);
}
for (const [role, list] of Object.entries(grantable)) {
  if (!roles[role]) throw new Error(`grantable: unknown role ${role}`);
  for (const r of list) if (!roles[r] || roles[r].scope === 'platform') throw new Error(`grantable.${role}: bad role ${r}`);
}
for (const p of [...orgWide, ...corporateOnly, ...superAdminOnly]) if (!permissions[p]) throw new Error(`unknown permission ${p}`);
const inAreas = areas.flatMap((a) => Object.keys(a.permissions));
for (const p of Object.keys(permissions)) {
  const n = inAreas.filter((x) => x === p).length;
  if (n !== 1) throw new Error(`${p} must be in exactly one area (is in ${n})`);
}
for (const p of inAreas) if (!permissions[p]) throw new Error(`area lists unknown permission ${p}`);
// Organization-wide roles cover every branch, so they may hold organization-wide permissions; a branch role holding one
// only gets it when given all branches (docs/RBAC.md §3).

// Permission codes: 2 characters each, carried in sign-in tokens (claims `p`). Append-only, so a token issued before
// a deploy still means the same thing after it; a removed permission keeps its code reserved.
const codesPath = join(root, 'firebase/rules-src/permission-codes.json');
const known = existsSync(codesPath) ? JSON.parse(readFileSync(codesPath, 'utf8')) : {};
const ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
const used = new Set(Object.values(known));
let next = 0;
const nextCode = () => {
  for (;;) {
    const c = ALPHABET[Math.floor(next / ALPHABET.length)] + ALPHABET[next % ALPHABET.length];
    next++;
    if (!used.has(c)) return used.add(c), c;
  }
};
const permCodes = { ...known };
for (const p of Object.keys(permissions)) if (!permCodes[p]) permCodes[p] = nextCode();
for (const c of Object.values(permCodes)) if (!/^[0-9a-zA-Z]{2}$/.test(c)) throw new Error(`bad permission code ${c}`);

const header = '// GENERATED by tools/rbac/generate.mjs from firebase/rules-src/permissions.json. Do not edit.\n';

const permsFn =
  '    // GENERATED permission → code map (tools/rbac/generate.mjs). Do not edit here.\n' +
  '    function perms() {\n      return {\n' +
  Object.keys(permissions)
    .map((p) => `        '${p}': '${permCodes[p]}'`)
    .join(',\n') +
  '\n      };\n    }';
const tmpl = readFileSync(join(root, 'firebase/rules-src/firestore.rules.tmpl'), 'utf8');
if (!tmpl.includes('/*@@PERMISSIONS@@*/')) throw new Error('template is missing /*@@PERMISSIONS@@*/');
const rules = '// GENERATED from firebase/rules-src/firestore.rules.tmpl. Edit the template, then `npm run gen:rbac`.\n' +
  tmpl.replace('    /*@@PERMISSIONS@@*/', permsFn);
if (/allow\s+read\s*,\s*write\s*:\s*if\s+request\.auth\s*!=\s*null/.test(rules)) {
  throw new Error('Refusing to generate rules containing a blanket signed-in read/write grant');
}

const ts =
  header +
  `export const ROLES = ${JSON.stringify(roles, null, 2)} as const;\n\n` +
  `export type Role = keyof typeof ROLES;\n` +
  `export type RoleCode = (typeof ROLES)[Role]['code'];\n\n` +
  `export const PERMISSIONS = ${JSON.stringify(permissions, null, 2)} as const satisfies Record<string, readonly string[]>;\n\n` +
  `export type Permission = keyof typeof PERMISSIONS;\n\n` +
  `/** Each permission's code in sign-in tokens (claims \`p\`, two characters each). */\n` +
  `export const PERMISSION_CODES: Record<Permission, string> = ${JSON.stringify(Object.fromEntries(Object.keys(permissions).map((p) => [p, permCodes[p]])), null, 2)};\n\n` +
  `/** Count only for someone whose access covers all branches. */\n` +
  `export const ORG_WIDE: readonly Permission[] = ${JSON.stringify(orgWide)};\n\n` +
  `/** Count only in the corporate organization (head office: the shared catalogue, the website). */\n` +
  `export const CORPORATE_ONLY: readonly Permission[] = ${JSON.stringify(corporateOnly)};\n\n` +
  `/** Never in a role of one's own. */\n` +
  `export const SUPER_ADMIN_ONLY: readonly Permission[] = ${JSON.stringify(superAdminOnly)};\n\n` +
  `/** The permissions grouped as the role editor shows them. */\n` +
  `export const AREAS: readonly { key: string; name: string; permissions: Partial<Record<Permission, string>> }[] = ${JSON.stringify(areas, null, 2)};\n\n` +
  `export const GRANTABLE: Partial<Record<Role, readonly Role[]>> = ${JSON.stringify(grantable, null, 2)};\n`;

const outputs = {
  'firebase/rules-src/permission-codes.json': JSON.stringify(permCodes, null, 2) + '\n',
  'firebase/firestore.rules': rules,
  'functions/src/generated/rbac.ts': ts,
  'apps/web/src/generated/rbac.ts': ts,
};

const check = process.argv.includes('--check');
let stale = false;
for (const [rel, content] of Object.entries(outputs)) {
  const path = join(root, rel);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === content) continue;
  if (check) {
    console.error(`stale: ${rel} (run npm run gen:rbac)`);
    stale = true;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${rel}`);
  }
}
if (stale) process.exit(1);
